attempts.candidate:
import { db } from "@/lib/db";

export async function GET(request: Request) {
  const { q } = new URL(request.url);
  const broadcasts = await db.broadcast.findMany({
    where: {
      title: {
        contains: q,
        mode: "insensitive",
      },
    },
    include: {
      transmitter: true,
    },
  });

  return new Response(JSON.stringify({ broadcasts, total: broadcasts.length }), {
    status: 200,
  });
}

